<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Perubahan Tunjangan Keluarga</title><style>body{margin:0;background:#eef2f6;font-family:Arial,sans-serif;color:#243447}.wrap{max-width:850px;margin:32px auto;padding:0 16px}.card{background:#fff;border-radius:14px;padding:24px;box-shadow:0 8px 30px #15314a18}h1{color:#15314a;margin:0}p{color:#64748b}.grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}.field{margin-top:12px}label{display:block;font-size:12px;font-weight:700;color:#15314a;margin-bottom:5px}input,textarea,select{box-sizing:border-box;width:100%;padding:10px;border:1px solid #ccd5df;border-radius:8px}textarea{min-height:80px}.member{border:1px solid #dde4ec;border-radius:10px;padding:12px;margin-top:12px}.btn{border:0;border-radius:8px;padding:10px 16px;background:#15314a;color:#fff;font-weight:700;cursor:pointer}.secondary{background:#e7edf3;color:#15314a}.success{padding:12px;background:#e4f5ed;color:#166534;border-radius:8px}.error{padding:12px;background:#fdecea;color:#b3261e;border-radius:8px}small{color:#64748b}@media(max-width:650px){.grid{grid-template-columns:1fr}}</style></head><body><div class="wrap"><div class="card"><h1>Form Perubahan Tunjangan Keluarga</h1><p>Isi data terbaru dan unggah dokumen pendukung. Berkas disimpan secara private dan hanya dapat diakses petugas berwenang.</p>@if(session('success'))<div class="success">{{ session('success') }}</div>@endif @if($errors->any())<div class="error"><ul>@foreach($errors->all() as $e)<li>{{ $e }}</li>@endforeach</ul></div>@endif
