<div id="anak-list">@foreach(old('anak',[[]]) as $i=>$anak)<div class="member anak"><strong>Anak</strong><div class="grid"><div class="field"><label>Nama</label><input name="anak[{{ $i }}][nama]" value="{{ $anak['nama']??'' }}"></div><div class="field"><label>Tanggal Lahir</label><input type="date" name="anak[{{ $i }}][tanggal_lahir]" value="{{ $anak['tanggal_lahir']??'' }}"></div></div><div class="grid"><label class="field"><input type="checkbox" name="anak[{{ $i }}][status_tunjangan]" value="1" style="width:auto" @checked($anak['status_tunjangan']??false)> Penerima tunjangan</label><label class="field"><input type="checkbox" name="anak[{{ $i }}][perpanjangan_kuliah]" value="1" style="width:auto" @checked($anak['perpanjangan_kuliah']??false)> Perpanjangan kuliah (usia 21–25)</label></div><div class="field"><label>Keterangan</label><input name="anak[{{ $i }}][keterangan]" value="{{ $anak['keterangan']??'' }}"></div></div>@endforeach</div><button type="button" class="btn secondary" id="add-anak" style="margin-top:12px">+ Tambah Anak</button><div class="field"><label>Keterangan Perubahan</label><textarea name="keterangan" required>{{ old('keterangan') }}</textarea></div><div class="field"><label>Lampiran private (PDF/JPG/PNG, maks. 5 MB)</label><input type="file" name="lampiran" accept=".pdf,.jpg,.jpeg,.png" required><small>Nama file pada penyimpanan akan diacak.</small></div><button class="btn" style="margin-top:18px">Kirim Pengajuan</button></form></div></div><script>document.getElementById('add-anak').addEventListener('click',()=>{const l=document.getElementById('anak-list'),i=l.children.length;if(i>=10)return;const d=document.createElement('div');d.className='member anak';d.innerHTML='<strong>Anak</strong><div class="grid"><div class="field"><label>Nama</label><input name="anak['+i+'][nama]"></div><div class="field"><label>Tanggal Lahir</label><input type="date" name="anak['+i+'][tanggal_lahir]"></div></div><div class="grid"><label class="field"><input type="check